package com.music.vivi.desktop

/**
 * Desktop string table. English is the primary (source) language; other
 * languages fall back to English until their translations are added under
 * the matching locale tag (e.g. `"it" to mapOf("search" to "Cerca", ...)`).
 *
 * The maps themselves live one per language, in `Localization_<lang>.kt`,
 * the way the APK keeps them in `values-<lang>/strings.xml`. This file is
 * GENERATED by `scripts/generate_desktop_localization.py` from the Android
 * app's resources — do not edit by hand.
 */
object Localization {
    private val strings: Map<String, Map<String, String>> = mapOf(
        "en" to strings_en(),
        "ar" to strings_ar(),
        "as" to strings_as(),
        "az" to strings_az(),
        "be" to strings_be(),
        "bg" to strings_bg(),
        "bn" to strings_bn(),
        "bs" to strings_bs(),
        "ca" to strings_ca(),
        "cs" to strings_cs(),
        "de" to strings_de(),
        "el" to strings_el(),
        "es" to strings_es(),
        "et" to strings_et(),
        "eu" to strings_eu(),
        "fa" to strings_fa(),
        "fi" to strings_fi(),
        "fil" to strings_fil(),
        "fr" to strings_fr(),
        "hi" to strings_hi(),
        "hr" to strings_hr(),
        "hu" to strings_hu(),
        "id" to strings_id(),
        "in" to strings_in(),
        "it" to strings_it(),
        "iw" to strings_iw(),
        "ja" to strings_ja(),
        "km" to strings_km(),
        "ko" to strings_ko(),
        "lt" to strings_lt(),
        "ml" to strings_ml(),
        "ms" to strings_ms(),
        "nb" to strings_nb(),
        "nb-rNO" to strings_nb_rNO(),
        "nl" to strings_nl(),
        "pa" to strings_pa(),
        "pl" to strings_pl(),
        "pt" to strings_pt(),
        "pt-rBR" to strings_pt_rBR(),
        "ro" to strings_ro(),
        "ru" to strings_ru(),
        "sk" to strings_sk(),
        "sl" to strings_sl(),
        "sr" to strings_sr(),
        "sv" to strings_sv(),
        "ta" to strings_ta(),
        "te" to strings_te(),
        "th" to strings_th(),
        "tr" to strings_tr(),
        "uk" to strings_uk(),
        "vi" to strings_vi(),
        "zh-rCN" to strings_zh_rCN(),
        "zh-rTW" to strings_zh_rTW(),
    )
    fun get(language: String, key: String): String {
        val direct = strings[language]?.get(key)
        if (direct != null) return direct
        strings["en"]?.get(key)?.let { return it }
        // Safety net: a missing translation must never surface as a raw snake-
        // case key on screen. Fall back to the first dictionary that has a real
        // (non-key) translation, so even a gap in every map shows something
        // readable instead of "player_background_visualizer".
        for (map in strings.values) {
            map[key]?.takeIf { it != key }?.let { return it }
        }
        return key
    }
}
